CREATE TABLE IF NOT EXISTS edit_decisions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,kind TEXT NOT NULL,target_id TEXT NOT NULL,parameters JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS edit_decisions_project_created_idx ON edit_decisions(project_id,created_at DESC);
CREATE TABLE IF NOT EXISTS subtitle_cues(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,start_ms BIGINT NOT NULL,end_ms BIGINT NOT NULL,text TEXT NOT NULL,language TEXT,style JSONB NOT NULL DEFAULT '{"position":"bottom"}',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(start_ms>=0 AND end_ms>start_ms));
CREATE INDEX IF NOT EXISTS subtitle_cues_project_time_idx ON subtitle_cues(project_id,start_ms);
CREATE TABLE IF NOT EXISTS audio_mix_settings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,track_id UUID NOT NULL REFERENCES timeline_tracks(id) ON DELETE CASCADE,gain_db REAL NOT NULL DEFAULT 0,muted BOOLEAN NOT NULL DEFAULT false,ducking JSONB NOT NULL DEFAULT '{}',updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(project_id,track_id),CHECK(gain_db>=-60 AND gain_db<=24));
